import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, lineDiscount, lineVAT, invoiceTotals, addLine, removeLine, issueInvoice } from '../src/invoices.js';

test('createInvoice creates a draft invoice with product details', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-001');
  assert.equal(r.value.issueDate, '2026-10-07');
  assert.equal(r.value.status, 'draft');
  assert.equal(r.value.lines.length, 1);
  assert.equal(r.value.lines[0].sku, 'DES-HOUR');
  assert.equal(r.value.lines[0].name, 'Design work (hour)');
  assert.equal(r.value.lines[0].qty, 5);
  assert.equal(r.value.lines[0].unitPrice, 8500);
  assert.equal(r.value.lines[0].vatRate, 21);
});

test('createInvoice normalizes customer ID', () => {
  const r = createInvoice({
    customerId: 'c-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-001');
});

test('createInvoice normalizes customer ID with spaces', () => {
  const r = createInvoice({
    customerId: '  c-001  ',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-001');
});

test('createInvoice handles multiple lines', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 3 },
      { sku: 'DEV-HOUR', qty: 10 },
    ],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines.length, 2);
  assert.equal(r.value.lines[0].name, 'Design work (hour)');
  assert.equal(r.value.lines[1].name, 'Development (hour)');
});

test('createInvoice rejects unknown customer', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-999',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'CUSTOMER_NOT_FOUND' }
  );
});

test('createInvoice rejects invalid date format', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '07-10-2026',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );
});

test('createInvoice rejects non-existent date', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-02-30',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );
});

test('createInvoice rejects empty lines array', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [],
    }),
    { ok: false, error: 'NO_LINES' }
  );
});

test('createInvoice rejects zero quantity', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 0 }],
    }),
    { ok: false, error: 'QTY_INVALID' }
  );
});

test('createInvoice rejects negative quantity', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: -5 }],
    }),
    { ok: false, error: 'QTY_INVALID' }
  );
});

test('createInvoice rejects fractional quantity', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 2.5 }],
    }),
    { ok: false, error: 'QTY_INVALID' }
  );
});

test('createInvoice rejects unknown SKU', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'NOPE', qty: 1 }],
    }),
    { ok: false, error: 'UNKNOWN_SKU' }
  );
});

test('createInvoice does not mutate arguments', () => {
  const lines = [{ sku: 'DES-HOUR', qty: 5 }];
  createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines,
  });
  assert.equal(lines[0].sku, 'DES-HOUR');
  assert.equal(lines[0].qty, 5);
  assert.equal(Object.keys(lines[0]).length, 2);
});

test('lineTotal calculates qty times unitPrice', () => {
  assert.equal(lineTotal({ qty: 5, unitPrice: 8500 }), 42500);
  assert.equal(lineTotal({ qty: 1, unitPrice: 100 }), 100);
  assert.equal(lineTotal({ qty: 10, unitPrice: 1 }), 10);
});

test('invoiceTotals sums line totals', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 8500, discountPercent: 0, vatRate: 0 },
      { qty: 10, unitPrice: 9500, discountPercent: 0, vatRate: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 5 * 8500 + 10 * 9500);
  assert.equal(totals.subtotal, 137500);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 137500);
});

test('invoiceTotals handles single line', () => {
  const invoice = {
    lines: [{ qty: 3, unitPrice: 6000, discountPercent: 0, vatRate: 0 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 18000);
  assert.equal(totals.total, 18000);
});

test('invoiceTotals handles empty lines', () => {
  const invoice = { lines: [] };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 0);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 0);
});

test('invoiceTotals with full invoice from createInvoice', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 3, discountPercent: 0 },
      { sku: 'DEV-HOUR', qty: 2, discountPercent: 0 },
    ],
  });
  assert.equal(r.ok, true);
  const totals = invoiceTotals(r.value);
  const expectedSubtotal = 3 * 8500 + 2 * 9500;
  const expectedVAT = Math.round(3 * 8500 * 0.21) + Math.round(2 * 9500 * 0.21);
  assert.equal(totals.subtotal, expectedSubtotal);
  assert.equal(totals.vat, expectedVAT);
  assert.equal(totals.total, expectedSubtotal + expectedVAT);
});

test('createInvoice accepts discountPercent on lines', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2, discountPercent: 10 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].discountPercent, 10);
});

test('createInvoice rejects invalid discountPercent', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 2, discountPercent: 150 }],
    }),
    { ok: false, error: 'DISCOUNT_INVALID' }
  );
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 2, discountPercent: -10 }],
    }),
    { ok: false, error: 'DISCOUNT_INVALID' }
  );
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 2, discountPercent: 'not a number' }],
    }),
    { ok: false, error: 'DISCOUNT_INVALID' }
  );
});

test('createInvoice applies tier discount when discountPercent not provided', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].discountPercent, 5);
});

test('createInvoice applies silver tier discount', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].discountPercent, 2.5);
});

test('createInvoice applies standard tier discount (0)', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].discountPercent, 0);
});

test('createInvoice prefers explicit discountPercent over tier discount', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2, discountPercent: 10 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].discountPercent, 10);
});

test('createInvoice respects explicit 0 discount over tier discount', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2, discountPercent: 0 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].discountPercent, 0);
});

test('lineDiscount calculates discount amount', () => {
  assert.equal(lineDiscount({ qty: 10, unitPrice: 1000, discountPercent: 10 }), 1000);
  assert.equal(lineDiscount({ qty: 2, unitPrice: 8500, discountPercent: 50 }), 8500);
  assert.equal(lineDiscount({ qty: 1, unitPrice: 100, discountPercent: 0 }), 0);
});

test('invoiceTotals includes discount', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 2, discountPercent: 10 },
      { sku: 'DEV-HOUR', qty: 1, discountPercent: 20 },
    ],
  });
  assert.equal(r.ok, true);
  const totals = invoiceTotals(r.value);
  const subtotal = 2 * 8500 + 1 * 9500;
  const discount = Math.round(2 * 8500 * 0.1) + Math.round(1 * 9500 * 0.2);
  const vat = Math.round((2 * 8500 - Math.round(2 * 8500 * 0.1)) * 0.21) + Math.round((1 * 9500 - Math.round(1 * 9500 * 0.2)) * 0.21);
  assert.equal(totals.subtotal, subtotal);
  assert.equal(totals.discount, discount);
  assert.equal(totals.vat, vat);
  assert.equal(totals.total, subtotal - discount + vat);
});

test('invoiceTotals clamps total to 0 if discount exceeds subtotal', () => {
  const invoice = {
    lines: [{ qty: 1, unitPrice: 1000, discountPercent: 200, vatRate: 0 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 1000);
  assert.equal(totals.discount, 2000);
  assert.equal(totals.total, 0);
});

test('lineVAT calculates VAT on amount after discount', () => {
  assert.equal(lineVAT({ qty: 1, unitPrice: 10000, discountPercent: 0, vatRate: 21 }), 2100);
  assert.equal(lineVAT({ qty: 1, unitPrice: 10000, discountPercent: 10, vatRate: 21 }), 1890);
});

test('lineVAT handles different VAT rates', () => {
  const line9 = { qty: 1, unitPrice: 10000, discountPercent: 0, vatRate: 9 };
  const line21 = { qty: 1, unitPrice: 10000, discountPercent: 0, vatRate: 21 };
  const line0 = { qty: 1, unitPrice: 10000, discountPercent: 0, vatRate: 0 };
  assert.equal(lineVAT(line9), 900);
  assert.equal(lineVAT(line21), 2100);
  assert.equal(lineVAT(line0), 0);
});

test('invoiceTotals includes VAT', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 1, discountPercent: 0 },
      { sku: 'PRINT-A4', qty: 1, discountPercent: 0 },
    ],
  });
  assert.equal(r.ok, true);
  const totals = invoiceTotals(r.value);
  assert.ok(totals.vat > 0);
});

test('invoiceTotals VAT formula is correct', () => {
  const invoice = {
    lines: [
      { qty: 2, unitPrice: 5000, discountPercent: 10, vatRate: 21 },
      { qty: 1, unitPrice: 10000, discountPercent: 0, vatRate: 9 },
    ],
  };
  const totals = invoiceTotals(invoice);
  const subtotal = 2 * 5000 + 1 * 10000;
  const discount = Math.round(2 * 5000 * 0.1) + Math.round(1 * 10000 * 0);
  const vat = Math.round((2 * 5000 - Math.round(2 * 5000 * 0.1)) * 0.21) + Math.round((1 * 10000) * 0.09);
  const expectedTotal = subtotal - discount + vat;
  assert.equal(totals.subtotal, subtotal);
  assert.equal(totals.discount, discount);
  assert.equal(totals.vat, vat);
  assert.equal(totals.total, expectedTotal);
});

test('addLine adds a new line to the invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 3 }],
  });
  assert.equal(r.ok, true);
  const invoice = r.value;

  const r2 = addLine(invoice, { sku: 'DEV-HOUR', qty: 2 });
  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines.length, 2);
  assert.equal(r2.value.lines[1].sku, 'DEV-HOUR');
  assert.equal(r2.value.lines[1].qty, 2);
  assert.equal(r2.value.lines[1].name, 'Development (hour)');
});

test('addLine increases qty if SKU already exists', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 3 }],
  });
  assert.equal(r.ok, true);

  const r2 = addLine(r.value, { sku: 'DES-HOUR', qty: 2 });
  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines.length, 1);
  assert.equal(r2.value.lines[0].qty, 5);
});

test('addLine validates quantity', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 3 }],
  });
  assert.equal(r.ok, true);

  assert.deepEqual(addLine(r.value, { sku: 'DEV-HOUR', qty: 0 }), {
    ok: false,
    error: 'QTY_INVALID',
  });
  assert.deepEqual(addLine(r.value, { sku: 'DEV-HOUR', qty: -5 }), {
    ok: false,
    error: 'QTY_INVALID',
  });
  assert.deepEqual(addLine(r.value, { sku: 'DEV-HOUR', qty: 2.5 }), {
    ok: false,
    error: 'QTY_INVALID',
  });
});

test('addLine validates SKU', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 3 }],
  });
  assert.equal(r.ok, true);

  assert.deepEqual(addLine(r.value, { sku: 'NOPE', qty: 1 }), {
    ok: false,
    error: 'UNKNOWN_SKU',
  });
});

test('addLine accepts discountPercent', () => {
  const r = createInvoice({
